// Compact, inline procedural noise generator
// NOTE: We use ubuf.u_time because the shortcut 't' is not accessible here!
vec3 p = floor(pModel * 3.0 + ubuf.u_time * 0.5);
vec3 f = fract(pModel * 3.0 + ubuf.u_time * 0.5);
f = f * f * (3.0 - 2.0 * f);
float n = p.x + p.y * 57.0 + 113.0 * p.z;
float baseNoise = mix(mix(fract(sin(n)*43758.5), fract(sin(n+1.0)*43758.5), f.x),
                      mix(fract(sin(n+57.0)*43758.5), fract(sin(n+58.0)*43758.5), f.x), f.y);

// 1. Color based on verticality (snow/light from above)
float snowLine = smoothstep(0.3, 0.8, n_model.y);

// 2. Color based on the cavities (uses the noise just computed)
float crevice = smoothstep(0.2, 0.7, baseNoise);

// 3. Procedural palette from your UI colors (u_col1 and u_col2)
vec3 rockColor = mix(ubuf.u_col2, ubuf.u_col1, crevice);

// 4. Final result
textureCol = mix(rockColor, vec3(0.9, 0.95, 1.0), snowLine * 0.5);
